import Link from "next/link";
import { ArrowUpRight, Camera, ShieldCheck } from "lucide-react";

export default function DashboardProfileCard({ name, email, role, image }: { name: string; email: string; role: string; image?: string | null }) {
  return <section className="rounded-2xl border border-slate-800 bg-slate-900 p-5 shadow-xl"><div className="flex flex-col gap-5 sm:flex-row sm:items-center sm:justify-between"><div className="flex items-center gap-4"><div className="relative flex h-16 w-16 shrink-0 items-center justify-center overflow-hidden rounded-2xl border border-indigo-500/30 bg-indigo-600/20 text-xl font-bold text-indigo-300">{image ? <img src={image} alt={`${name} profile`} className="h-full w-full object-cover" /> : name.charAt(0).toUpperCase()}<span className="absolute bottom-1 right-1 flex h-5 w-5 items-center justify-center rounded-full border-2 border-slate-900 bg-indigo-500 text-white"><Camera size={10} aria-hidden="true" /></span></div><div><p className="text-sm font-semibold text-white">{name}</p><p className="mt-1 text-xs text-slate-400">{email}</p><p className="mt-2 inline-flex items-center gap-1.5 text-[10px] font-semibold uppercase tracking-wider text-emerald-400"><ShieldCheck size={12} aria-hidden="true" /> {role} profile</p></div></div><Link href="/dashboard/settings" className="inline-flex items-center justify-center gap-1.5 rounded-lg border border-slate-700 px-3 py-2 text-xs font-semibold text-slate-300 transition-colors hover:bg-slate-800 hover:text-white">Manage profile <ArrowUpRight size={13} aria-hidden="true" /></Link></div></section>;
}